Here is the original GNU C++14 code you have to translate:
<original_code>
#include <algorithm>
#include <iostream>
#include <cstring>
#include <cstdio>
#include <vector>
#include <cctype>

#define File(a) freopen(a".in", "r", stdin), freopen(a".out", "w", stdout)

using std::pair;
using std::make_pair;

#define pii pair<int, int>
#define mp make_pair

using ll = long long;
const int inf = 1e9;
const ll infll = 0ll + 1e18;

#define int long long
const int mod1 = 998244353;
const int mod2 = 1e9 + 7;
const int Base = 1000000;

int n, tot, sum[15], ans;
int vec[15][1000001]; // max size for depth 6 is 10^6
int sz_vec[15];

void dfs1_array();
void dfs2_array();

signed main(void) {
  std::cin >> n;
  dfs1_array();
  for (int i = 0; i <= 7; i++)
    std::sort(vec[i], vec[i] + sz_vec[i]);
  tot = 0;
  dfs2_array();
  std::cout << ans << std::endl;
  return 0;
}

void dfs1_array() {
  struct Node { int k, num; };
  std::vector<Node> stack;
  stack.push_back({0, 0});
  while (!stack.empty()) {
    Node cur = stack.back();
    stack.pop_back();
    if (cur.k == 7) continue;
    tot++;
    int back = ((tot - cur.num) % mod1 + mod1) % mod1;
    vec[cur.k][sz_vec[cur.k]++] = back;
    sum[cur.k] = (sum[cur.k] + back) % mod2;
    for (int i = 9; i >= 0; i--)
      stack.push_back({cur.k + 1, cur.num * 10 + i});
  }
}

void dfs2_array() {
  struct Node { int x; };
  std::vector<Node> stack;
  for (int x0 = 9; x0 >= 1; x0--) stack.push_back({x0});
  while (!stack.empty()) {
    Node cur = stack.back();
    stack.pop_back();
    if (cur.x > n) continue;
    if (cur.x * Base + Base - 1 <= n && cur.x * Base * 10 > n) {
      int now = tot;
      for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
        int sz = sz_vec[i];
        int dif = ((now - cur.x * mul) % mod1 + mod1) % mod1;
        int pos = std::lower_bound(vec[i], vec[i] + sz, mod1 - dif) - vec[i];
        ans = (ans + dif * sz + sum[i]) % mod2;
        ans = (ans - mod1 * (sz - pos) % mod2 + mod2) % mod2;
        tot += sz;
      }
      continue;
    }
    tot++;
    ans = (ans + ((tot - cur.x) % mod1 + mod1) % mod1) % mod2;
    for (int i = 9; i >= 0; i--)
      stack.push_back({cur.x * 10 + i});
  }
}
